const payload = $json;
const configuredSecret = ($env.N8N_WEBHOOK_SECRET || '').trim();
if (!configuredSecret) {
  return [{ json: { ok: true, payload, warning: 'N8N_WEBHOOK_SECRET is not set', receivedAt: new Date().toISOString() } }];
}
const headers = payload.headers || payload.header || {};
const receivedSecret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || '';
const ok = receivedSecret === configuredSecret;
return [{ json: { ok, payload, receivedAt: new Date().toISOString(), error: ok ? null : 'invalid_webhook_secret' } }];

const payload = $json.payload || $json;
return [{
  json: {
    workflow: 'bellus-appointment-canceled',
    event: payload.event || 'appointment_canceled',
    appointment: payload.appointment || null,
    manageUrl: payload.manageUrl || null,
    sentAt: payload.sentAt || null,
    receivedAt: new Date().toISOString()
  }
}];

return [{
  json: {
    workflow: 'bellus-appointment-canceled',
    severity: 'error',
    reason: $json.error || 'invalid_webhook_secret',
    event: ($json.payload && $json.payload.event) || 'appointment_canceled',
    sentAt: ($json.payload && $json.payload.sentAt) || null,
    receivedAt: new Date().toISOString(),
    payload: $json.payload || null
  }
}];

const FONT_HEADING = "'Playfair Display', Georgia, 'Times New Roman', Times, serif";
const FONT_BODY = "Lato, Arial, Helvetica, sans-serif";
const FONT_IMPORT =
  "@import url('https://fonts.googleapis.com/css2?family=Lato:ital,wght@0,400;0,700;1,400&family=Playfair+Display:ital,wght@0,700;1,700&display=swap');";

function esc(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function envStr(env, key, fallback) {
  const raw = env && env[key];
  const value = raw == null ? "" : String(raw).trim();
  return value || fallback || "";
}

function appBase(env) {
  return envStr(env, "BELLUS_APP_URL", envStr(env, "NEXT_PUBLIC_APP_URL", "http://localhost:3000")).replace(/\/$/, "");
}

function asset(env, path) {
  return appBase(env) + path;
}

function localeOf(data) {
  const raw = (data && data.locale) || (data && data.appointment && data.appointment.locale);
  return raw === "en" ? "en" : "es";
}

function statusLabel(status, locale) {
  const maps = {
    es: {
      pending: "pendiente",
      confirmed: "confirmada",
      cancelled: "cancelada",
      completed: "completada",
      no_show: "no-show",
    },
    en: {
      pending: "pending",
      confirmed: "confirmed",
      cancelled: "cancelled",
      completed: "completed",
      no_show: "no-show",
    },
  };
  const map = maps[locale] || maps.es;
  return map[status] || status || "";
}

function fmtWhen(iso, locale) {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return String(iso);
  const tag = locale === "en" ? "en-CA" : "es-CA";
  try {
    return date.toLocaleString(tag, {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch (e) {
    return date.toISOString();
  }
}

function labelsFor(locale) {
  return locale === "en"
    ? {
        when: "When",
        until: "Until",
        status: "Status",
        event: "Event",
        appointment: "Appointment",
        client: "Client",
        email: "Email",
        previous: "Previous",
        reason: "Reason",
        destination: "Destination",
        followUs: "Follow us",
        unsubscribe: "Unsubscribe",
        viewInBrowser: "View in browser",
        helloFallback: "there",
        previousFallback: "the previous time",
      }
    : {
        when: "Cuándo",
        until: "Hasta",
        status: "Estado",
        event: "Evento",
        appointment: "Cita",
        client: "Cliente",
        email: "Email",
        previous: "Anterior",
        reason: "Motivo",
        destination: "Destino",
        followUs: "Síguenos",
        unsubscribe: "Cancelar suscripción",
        viewInBrowser: "Ver en el navegador",
        helloFallback: "hola",
        previousFallback: "la hora anterior",
      };
}

function socialRow(env, locale) {
  const base = appBase(env);
  const items = [
    ["N8N_SOCIAL_INSTAGRAM", "/brand/social-instagram.png", "Instagram"],
    ["N8N_SOCIAL_FACEBOOK", "/brand/social-facebook.png", "Facebook"],
    ["N8N_SOCIAL_X", "/brand/social-x.png", "X"],
    ["N8N_SOCIAL_WHATSAPP", "/brand/social-whatsapp.png", "WhatsApp"],
  ].filter(function (row) {
    return envStr(env, row[0], "");
  });
  if (!items.length) return "";
  const cells = items
    .map(function (row) {
      return (
        '<td style="padding:0 6px;"><a href="' +
        esc(envStr(env, row[0], "#")) +
        '" style="text-decoration:none;"><img src="' +
        esc(base + row[1]) +
        '" width="32" height="32" alt="' +
        esc(row[2]) +
        '" style="display:block;border:0;width:32px;height:32px;"></a></td>'
      );
    })
    .join("");
  return (
    '<p style="margin:16px 0 8px;font-family:' +
    FONT_BODY +
    ';font-size:12px;letter-spacing:1px;color:#593432;text-transform:uppercase;">' +
    esc(labelsFor(locale).followUs) +
    "</p>" +
    '<table role="presentation" cellpadding="0" cellspacing="0" align="center"><tr>' +
    cells +
    "</tr></table>"
  );
}

function detailsTable(rows) {
  const body = rows
    .filter(function (row) {
      return row && row[1];
    })
    .map(function (row) {
      return (
        '<tr><td style="padding:7px 0;font-family:' +
        FONT_BODY +
        ';font-size:13px;color:#E6C2BF;">' +
        esc(row[0]) +
        '</td><td style="padding:7px 0 7px 16px;font-family:' +
        FONT_BODY +
        ';font-size:13px;color:#FFFFFF;text-align:right;">' +
        esc(row[1]) +
        "</td></tr>"
      );
    })
    .join("");
  if (!body) return "";
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:12px 0 4px;">' + body + "</table>";
}

