const FALLBACK = {
  es: {
    client: { headline: "Bellus Lab", preheader: "Un aviso de Bellus Lab.", intro: "Hola {name}, tienes una actualización de tu cita.", cta: "Ver mi reserva" },
    ops: { headline: "Aviso Bellus", preheader: "Evento de Bellus Lab.", intro: "Hay una actualización operativa.", cta: "Abrir app" },
    error: { headline: "Alerta", preheader: "Falló un flujo de Bellus Lab.", intro: "Algo no se pudo completar. Revisa el detalle y el secreto del webhook si aplica.", cta: "Abrir app" },
  },
  en: {
    client: { headline: "Bellus Lab", preheader: "A note from Bellus Lab.", intro: "Hi {name}, you have an update about your appointment.", cta: "Manage my booking" },
    ops: { headline: "Bellus notice", preheader: "Bellus Lab event.", intro: "There is an operational update.", cta: "Open app" },
    error: { headline: "Alert", preheader: "A Bellus Lab workflow failed.", intro: "Something could not be completed. Check the details and the webhook secret if needed.", cta: "Open app" },
  },
};

function copyFor(event, kind, locale) {
  const catalog = locale === "en" && kind === "client" ? COPY_EN : COPY_ES;
  const fallback = FALLBACK[locale] || FALLBACK.es;
  const entry = catalog[event] || {};
  return entry[kind] || (COPY_ES[event] && COPY_ES[event][kind]) || fallback[kind] || fallback.ops;
}

function appointmentFrom(data) {
  return (data && data.appointment) || {};
}

function fillIntro(template, data, locale) {
  const apt = appointmentFrom(data);
  const labels = labelsFor(locale);
  return template
    .replace(/\{name\}/g, apt.client_name || labels.helloFallback)
    .replace(/\{previous\}/g, fmtWhen(data && data.previousStartAt, locale) || labels.previousFallback);
}

function buildBellusEmail(env, data, kind) {
  const apt = appointmentFrom(data);
  const event = (data && (data.event || data.workflow)) || "";
  const isError = kind === "error";
  const locale = kind === "client" ? localeOf(data) : "es";
  const labels = labelsFor(locale);
  const copy = copyFor(isError ? "error" : event, isError ? "error" : kind, locale);
  const headline = copy.headline;
  const preheader = copy.preheader;
  const intro = fillIntro(copy.intro, data, locale);
  const ctaLabel = copy.cta;
  const url =
    isError
      ? appBase(env)
      : kind === "ops" && (event === "payment_success" || event === "payment_refunded")
        ? appBase(env) + "/crm/payments"
        : (data && data.manageUrl) || appBase(env) + "/reservas";
  const name = apt.client_name || "Bellus Lab";
  const subjectBase = headline.replace(/<br>/g, " ").replace(/\s+/g, " ").trim();
  const subject =
    kind === "client"
      ? subjectBase + " · Bellus Lab"
      : isError
        ? "[Bellus][ERROR] " + ((data && data.reason) || (data && data.workflow) || "alerta")
        : "[Bellus] " + (event || "aviso") + (apt.id ? " " + apt.id : "");

  const detailRows =
    kind === "client"
      ? [
          [labels.when, fmtWhen(apt.start_at, locale)],
          [labels.until, fmtWhen(apt.end_at, locale)],
          [labels.status, statusLabel(apt.status, locale)],
        ]
      : [
          [labels.event, event || (data && data.workflow)],
          [labels.appointment, apt.id],
          [labels.client, apt.client_name],
          [labels.email, apt.client_email],
          [labels.when, fmtWhen(apt.start_at, locale)],
          [labels.status, statusLabel(apt.status, locale)],
          [labels.previous, fmtWhen(data && data.previousStartAt, locale)],
          [labels.reason, data && (data.reason || data.errorMessage)],
          [labels.destination, data && data.targetWebhook],
        ];

  const extraNote =
    kind === "client"
      ? ""
      : isError
        ? '<p style="margin:16px 0 0;font-family:' +
          FONT_BODY +
          ';font-size:13px;line-height:1.55;color:#FFFFFF;">' +
          esc((data && (data.reason || data.error || data.errorMessage)) || "Error no especificado.") +
          "</p>"
        : "";

  const logo = asset(env, "/brand/logo-email-light.png");
  const footerLogo = asset(env, "/brand/logo-email-footer.png");
  const hero = asset(env, "/brand/email-hero.png");
  const diamond = asset(env, "/brand/email-diamond.png");
  const address = envStr(env, "N8N_STUDIO_ADDRESS", "Bellus Lab");
  const unsub = envStr(env, "N8N_UNSUBSCRIBE_URL", url);

  const html =
    '<!DOCTYPE html><html lang="' +
    locale +
    '"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' +
    esc(subjectBase) +
    "</title><style>" +
    FONT_IMPORT +
    "</style></head>" +
    '<body style="margin:0;padding:0;background:#F3E8E6;">' +
    '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#F3E8E6;">' +
    esc(preheader) +
    "</div>" +
    '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" bgcolor="#F3E8E6"><tr><td align="center" style="padding:28px 12px;">' +
    '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:600px;max-width:600px;background-color:#1A1412;background-image:linear-gradient(180deg,#1A1412 0%,#3B2321 42%,#E6C2BF 100%);">' +
    '<tr><td align="center" style="padding:40px 28px 8px;"><a href="' +
    esc(appBase(env)) +
    '" style="text-decoration:none;"><img src="' +
    esc(logo) +
    '" width="200" alt="belluslab." style="display:block;border:0;width:200px;height:auto;"></a></td></tr>' +
    '<tr><td align="center" style="padding:12px 32px 10px;font-family:' +
    FONT_HEADING +
    ';font-size:42px;line-height:1.15;letter-spacing:0.2px;color:#FFFFFF;font-weight:700;">' +
    headline +
    "</td></tr>" +
    '<tr><td align="center" style="padding:8px 24px 4px;"><img src="' +
    esc(hero) +
    '" width="552" alt="" style="display:block;border:0;width:100%;max-width:552px;height:auto;border-radius:8px;"></td></tr>' +
    '<tr><td style="padding:22px 48px 6px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' +
    '<td style="border-top:1px solid #E6C2BF;font-size:0;line-height:0;">&nbsp;</td>' +
    '<td width="28" align="center" style="padding:0 8px;"><img src="' +
    esc(diamond) +
    '" width="14" height="14" alt="" style="display:block;border:0;"></td>' +
    '<td style="border-top:1px solid #E6C2BF;font-size:0;line-height:0;">&nbsp;</td>' +
    "</tr></table></td></tr>" +
    '<tr><td align="center" style="padding:10px 48px 6px;font-family:' +
    FONT_BODY +
    ';font-size:16px;line-height:1.65;color:#FFFFFF;">' +
    esc(intro).replace(esc(name), "<strong>" + esc(name) + "</strong>") +
    extraNote +
    detailsTable(detailRows) +
    "</td></tr>" +
    '<tr><td align="center" style="padding:18px 48px 36px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td align="center" bgcolor="#1A1412" style="border-radius:28px;border:1px solid #B88917;">' +
    '<a href="' +
    esc(url) +
    '" style="display:inline-block;padding:14px 34px;font-family:' +
    FONT_BODY +
    ';font-size:13px;font-weight:bold;letter-spacing:0.8px;text-transform:uppercase;color:#FFFFFF;text-decoration:none;">' +
    esc(ctaLabel) +
    "</a></td></tr></table></td></tr>" +
    '<tr><td align="center" bgcolor="#FFFFFD" style="padding:28px 24px 10px;"><img src="' +
    esc(footerLogo) +
    '" width="168" alt="belluslab." style="display:block;border:0;width:168px;height:auto;">' +
    socialRow(env, locale) +
    "</td></tr>" +
    '<tr><td align="center" bgcolor="#FFFFFD" style="padding:8px 28px 28px;font-family:' +
    FONT_BODY +
    ';font-size:11px;line-height:1.6;color:#774440;">' +
    esc(address) +
    '<br><a href="' +
    esc(unsub) +
    '" style="color:#774440;text-decoration:underline;">' +
    esc(labels.unsubscribe) +
    '</a> &nbsp;|&nbsp; <a href="' +
    esc(url) +
    '" style="color:#774440;text-decoration:underline;">' +
    esc(labels.viewInBrowser) +
    "</a></td></tr>" +
    "</table></td></tr></table></body></html>";

  const text = [subjectBase, "", intro.replace(/<br>/g, " "), fmtWhen(apt.start_at, locale), url, "", "belluslab."].filter(Boolean).join("\n");
  return { html: html, text: text, subject: subject };
}

function decoratePayload(env, data) {
  const client = buildBellusEmail(env, data, "client");
  const ops = buildBellusEmail(env, data, "ops");
  const error = buildBellusEmail(env, Object.assign({}, data, { event: data.event || "error" }), "error");
  return Object.assign({}, data, {
    clientHtml: client.html,
    clientText: client.text,
    clientSubject: client.subject,
    opsHtml: ops.html,
