function esc(value) {
  return String(value == null ? "" : value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function envStr(env, key, fallback) {
  const raw = env && env[key];
  const value = raw == null ? "" : String(raw).trim();
  return value || fallback || "";
}

function appBase(env) {
  return envStr(env, "BELLUS_APP_URL", envStr(env, "NEXT_PUBLIC_APP_URL", "http://localhost:3000")).replace(/\/$/, "");
}

function asset(env, path) {
  return appBase(env) + path;
}

function localeOf(data) {
  const raw = (data && data.locale) || (data && data.appointment && data.appointment.locale);
  return raw === "en" ? "en" : "es";
}

function statusLabel(status, locale) {
  const maps = {
    es: {
      pending: "pendiente",
      confirmed: "confirmada",
      cancelled: "cancelada",
      completed: "completada",
      no_show: "no-show",
    },
    en: {
      pending: "pending",
      confirmed: "confirmed",
      cancelled: "cancelled",
      completed: "completed",
      no_show: "no-show",
    },
  };
  const map = maps[locale] || maps.es;
  return map[status] || status || "";
}

function fmtWhen(iso, locale) {
  if (!iso) return "";
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return String(iso);
  const tag = locale === "en" ? "en-CA" : "es-CA";
  try {
    return date.toLocaleString(tag, {
      weekday: "long",
      day: "numeric",
      month: "long",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch (e) {
    return date.toISOString();
  }
}

function labelsFor(locale) {
  return locale === "en"
    ? {
        when: "When",
        until: "Until",
        status: "Status",
        event: "Event",
        appointment: "Appointment",
        client: "Client",
        email: "Email",
        previous: "Previous",
        reason: "Reason",
        destination: "Destination",
        followUs: "Follow us",
        unsubscribe: "Unsubscribe",
        viewInBrowser: "View in browser",
        helloFallback: "there",
        previousFallback: "the previous time",
      }
    : {
        when: "Cuándo",
        until: "Hasta",
        status: "Estado",
        event: "Evento",
        appointment: "Cita",
        client: "Cliente",
        email: "Email",
        previous: "Anterior",
        reason: "Motivo",
        destination: "Destino",
        followUs: "Síguenos",
        unsubscribe: "Cancelar suscripción",
        viewInBrowser: "Ver en el navegador",
        helloFallback: "hola",
        previousFallback: "la hora anterior",
      };
}

function socialRow(env, locale) {
  const base = appBase(env);
  const items = [
    ["N8N_SOCIAL_INSTAGRAM", "/brand/social-instagram.png", "Instagram"],
    ["N8N_SOCIAL_FACEBOOK", "/brand/social-facebook.png", "Facebook"],
