    "</p>" +
    '<table role="presentation" cellpadding="0" cellspacing="0" align="center"><tr>' +
    cells +
    "</tr></table>"
  );
}

function detailsTable(rows) {
  const body = rows
    .filter(function (row) {
      return row && row[1];
    })
    .map(function (row) {
      return (
        '<tr><td style="padding:7px 0;font-family:' +
        FONT_BODY +
        ';font-size:13px;color:#E6C2BF;">' +
        esc(row[0]) +
        '</td><td style="padding:7px 0 7px 16px;font-family:' +
        FONT_BODY +
        ';font-size:13px;color:#FFFFFF;text-align:right;">' +
        esc(row[1]) +
        "</td></tr>"
      );
    })
    .join("");
  if (!body) return "";
  return '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:12px 0 4px;">' + body + "</table>";
}

